const { execFileSync } = await import('child_process');
const { dirname } = await import('path');
const commonDir = execFileSync('git', ['rev-parse', '--git-common-dir'], { cwd: $root, encoding: 'utf8' }).trim();
const repoRoot = dirname(commonDir);
const { parseFlagsTest } = await import(repoRoot + '/packages/main/dist/cli-engine.js');
return parseFlagsTest(['--name=koala', '--count=3', '--dry-run', '--tags=alpha', '--tags=beta', '--payload={"x":1}'], { name: 'string', count: 'number', dryRun: 'boolean', tags: 'array', payload: 'object' });

const { execFileSync } = await import('child_process');
const { dirname } = await import('path');
const commonDir = execFileSync('git', ['rev-parse', '--git-common-dir'], { cwd: $root, encoding: 'utf8' }).trim();
const repoRoot = dirname(commonDir);
const { parseFlags } = await import(repoRoot + '/packages/main/dist/cli-engine.js');
const { z } = await import('zod');
return parseFlags(['mode=legacy', '--tags', 'a', '--tags=b', '--limit', '5', '--flag'], { mode: z.string(), tags: z.array(z.string()), limit: z.number(), flag: z.boolean().optional() });

const { execFileSync } = await import('child_process');
const { dirname } = await import('path');
const commonDir = execFileSync('git', ['rev-parse', '--git-common-dir'], { cwd: $root, encoding: 'utf8' }).trim();
const repoRoot = dirname(commonDir);
const { coerce, addValue } = await import(repoRoot + '/packages/main/dist/cli-engine.js');
const { z } = await import('zod');
const bag = {};
addValue(bag, 'tags', 'alpha', true);
addValue(bag, 'tags', 'beta', true);
addValue(bag, 'mode', 'legacy', false);
addValue(bag, 'mode', 'override', false);
return { jsonValue: coerce('{"x":1}', z.string()), boolValue: coerce('true', z.string()), tags: bag.tags, mode: bag.mode };
